
#' Print PSA Parameter Distribution Diagnostics
#'
#' Prints a formatted summary of the numerical diagnostics
#' generated by [compute_psa()].
#'
#' The output compares theoretical distribution statistics
#' with the corresponding Monte Carlo estimates for all
#' probabilistic parameters.
#'
#' @param x An object of class `cea_parameter_diagnostics`,
#'   generated by [compute_psa()].
#' @param ... Additional arguments (currently unused).
#'
#' @details
#' The output includes the original probability distribution
#' specifications, when available, followed by a single table
#' containing five statistics per probabilistic parameter:
#' mean, median, standard deviation, 2.5th percentile,
#' and 97.5th percentile.
#'
#' Distribution specifications retain the original parameter
#' names and values supplied to [define_cea_parameters()].
#' This is particularly relevant for distributions whose
#' parameters do not directly represent their theoretical
#' mean and standard deviation.
#'
#' Differences are calculated as simulated minus theoretical
#' values.
#'
#' Numerical diagnostics are displayed with three decimal
#' places. Formatting does not modify the underlying data.
#'
#' @return Invisibly returns `x`, unchanged.
#'
#' @export
print.cea_parameter_diagnostics <- function(x, ...) {

  # ============================================================
  # 1. Validate input
  # ============================================================

  if (!inherits(x, "cea_parameter_diagnostics")) {
    stop(
      "'x' must be a 'cea_parameter_diagnostics' object."
    )
  }

  required_cols <- c(
    "parameter",
    "distribution",
    "R",
    "mean_theoretical",
    "mean_simulated",
    "mean_difference",
    "median_theoretical",
    "median_simulated",
    "median_difference",
    "sd_theoretical",
    "sd_simulated",
    "sd_difference",
    "p2.5_theoretical",
    "p2.5_simulated",
    "p2.5_difference",
    "p97.5_theoretical",
    "p97.5_simulated",
    "p97.5_difference"
  )

  if (!all(required_cols %in% names(x))) {
    stop(
      "The diagnostics object does not contain ",
      "all required columns."
    )
  }

  # ============================================================
  # 2. Prepare long-format display table
  # ============================================================

  statistics <- c(
    Mean = "mean",
    Median = "median",
    SD = "sd",
    P2.5 = "p2.5",
    P97.5 = "p97.5"
  )

  display_rows <- lapply(seq_len(nrow(x)), function(i) {

    parameter <- x$parameter[i]

    do.call(
      rbind,
      lapply(names(statistics), function(statistic) {

        prefix <- statistics[[statistic]]

        data.frame(
          Parameter = parameter,
          Statistic = statistic,
          Theoretical = x[[paste0(
            prefix, "_theoretical"
          )]][i],
          Simulated = x[[paste0(
            prefix, "_simulated"
          )]][i],
          Difference = x[[paste0(
            prefix, "_difference"
          )]][i],
          stringsAsFactors = FALSE
        )
      })
    )
  })

  display_table <- if (length(display_rows) > 0L) {
    do.call(rbind, display_rows)
  } else {
    data.frame(
      Parameter = character(),
      Statistic = character(),
      Theoretical = numeric(),
      Simulated = numeric(),
      Difference = numeric()
    )
  }

  rownames(display_table) <- NULL

  # ============================================================
  # 3. Format numerical values
  # ============================================================

  format_number <- function(value, signed = FALSE) {

    if (is.na(value)) {
      return("-")
    }

    if (signed) {
      return(sprintf("%+.3f", value))
    }

    sprintf("%.3f", value)
  }

  display_table$Theoretical <- vapply(
    display_table$Theoretical,
    format_number,
    character(1)
  )

  display_table$Simulated <- vapply(
    display_table$Simulated,
    format_number,
    character(1)
  )

  display_table$Difference <- vapply(
    display_table$Difference,
    format_number,
    character(1),
    signed = TRUE
  )

  # ============================================================
  # 4. Format original distribution specifications
  # ============================================================

  distribution_specs <- attr(
    x,
    "distribution_specs",
    exact = TRUE
  )

  format_spec_value <- function(value) {

    if (is.numeric(value)) {
      return(paste(
        format(value, trim = TRUE, scientific = FALSE),
        collapse = ", "
      ))
    }

    paste(as.character(value), collapse = ", ")
  }

  format_distribution <- function(parameter, distribution) {

    spec <- distribution_specs[[parameter]]

    if (is.null(spec)) {
      return(paste0(parameter, " (", distribution, ")"))
    }

    distribution_name <- spec$distribution

    if (is.null(distribution_name)) {
      distribution_name <- distribution
    }

    distribution_name <- switch(
      tolower(distribution_name),
      normal = "Normal",
      beta = "Beta",
      gamma = "Gamma",
      lognormal = "Lognormal",
      uniform = "Uniform",
      distribution_name
    )

    argument_names <- setdiff(
      names(spec),
      "distribution"
    )

    arguments <- vapply(
      argument_names,
      function(argument) {
        paste0(
          argument,
          " = ",
          format_spec_value(spec[[argument]])
        )
      },
      character(1)
    )

    paste0(
      parameter,
      ": ",
      distribution_name,
      "(",
      paste(arguments, collapse = ", "),
      ")"
    )
  }

  # ============================================================
  # 5. Print diagnostics
  # ============================================================

  cat("\nCEA PARAMETER DISTRIBUTION DIAGNOSTICS\n")
  cat(strrep("=", 60), "\n", sep = "")

  if (nrow(x) == 0L) {
    cat("\nNo parameter diagnostics available.\n")
    return(invisible(x))
  }

  cat(
    "\nProbabilistic parameters: ",
    nrow(x),
    "\n",
    sep = ""
  )

  iterations <- unique(x$R)

  if (length(iterations) == 1L) {
    cat(
      "Monte Carlo iterations: ",
      iterations,
      "\n",
      sep = ""
    )
  }

  cat("\nDISTRIBUTION SPECIFICATIONS\n")
  cat(strrep("-", 60), "\n", sep = "")

  for (i in seq_len(nrow(x))) {

    parameter <- x$parameter[i]
    distribution <- x$distribution[i]

    cat(
      format_distribution(
        parameter,
        distribution
      ),
      "\n",
      sep = ""
    )
  }

  cat("\nDISTRIBUTION STATISTICS\n")
  cat(strrep("-", 60), "\n", sep = "")

  print(
    display_table,
    row.names = FALSE,
    right = TRUE,
    quote = FALSE
  )

  cat("\n")
  cat("Difference = Simulated - Theoretical\n")

  invisible(x)
}
